import random, time, uuid

def call_with_resilience(operation, *, timeout_s=0.8, max_attempts=3):
    # Idempotency key lets safe retry: server dedupes on this key.
    # Trade-off: requires server-side dedupe store; buys storm-free retries.
    key = str(uuid.uuid4())
    backoff = 0.05
    for attempt in range(1, max_attempts + 1):
        try:
            return operation(idempotency_key=key, timeout=timeout_s)
        except TransientError:
            if attempt == max_attempts:
                raise
            # Exponential backoff + jitter spreads retries so replicas recover.
            time.sleep(backoff + random.uniform(0, backoff))
            backoff *= 2
        except TimeoutError:
            # Do NOT blindly retry non-idempotent work on timeout:
            # the first attempt may have succeeded server-side.
            raise
